from concurrent.futures import ThreadPoolExecutor

def square(x):
    return x * x

def main():
    with ThreadPoolExecutor() as pool:
        results = list(pool.map(square, [1, 2, 3, 4]))
    print(results)

if __name__ == "__main__":
    main()

